-- Visible projection: the archivist's list sorted on a conditionally visible column, ORDER BY CASE (trimmed to the columns that decide the plan; the ORDER BY and WHERE shapes are the renderer's).
SELECT Id, CASE WHEN `Missions`.`StatusId` IN ('completed', 'failed', 'stood_down') THEN SectorId ELSE '' END AS SectorId, CASE WHEN `Missions`.`StatusId` = 'completed' THEN Fee ELSE NUMERIC '0' END AS Fee, CASE WHEN `Missions`.`StatusId` IN ('completed', 'failed', 'stood_down') THEN Deadline ELSE TIMESTAMP '0001-01-01T00:00:00Z' END AS Deadline, ARRAY_CONCAT(IF(`Missions`.`StatusId` IN ('completed', 'failed', 'stood_down'), ARRAY<STRING>[], ['sectorId']), IF(`Missions`.`StatusId` = 'completed', ARRAY<STRING>[], ['fee'])) AS zzMaskedFields FROM Missions WHERE (`Missions`.`SectorId` = 'anvil') AND (`Missions`.`StatusId` IN ('open', 'claimed', 'underway') OR `Missions`.`StatusId` = 'completed') ORDER BY CASE WHEN `Missions`.`StatusId` IN ('completed', 'failed', 'stood_down') THEN `Deadline` END ASC, `Id` ASC LIMIT 26
